update community_post


         is_deleted = #{status},


         content = #{content},


        title = #{title}


where id=#{postId}
and status=1

mapper.select:
select p.id,p.user_id as authorId,p.title,p.content,p.create_time, u.username as authorName,u.avatar as authorAvatar, r.role_name as role from community_post p left join user u on p.user_id = u.id left join user_role ur on u.id = ur.user_id left join role r on ur.role_id = r.id where
r.id=#{role}
and (p.title like concat('%',#{key},'%') or p.content like concat('%',#{key},'%'))
and p.status = #{status}
order by p.create_time desc

